import jakarta.persistence.*;
import java.util.*;

@Entity
public class Order {
    @Id @GeneratedValue private Long id;

    @OneToMany(mappedBy = "order", fetch = FetchType.LAZY)  // explicit LAZY
    private List<OrderItem> items = new ArrayList<>();

    @ManyToOne(fetch = FetchType.EAGER)                     // explicit EAGER
    private Customer customer;
    public Customer getCustomer() { return customer; }
    public List<OrderItem> getItems() { return items; }
}

@org.springframework.stereotype.Service
class OrderService {
    @org.springframework.transaction.annotation.Transactional
    public void processOrder(Long orderId) {
        Order order = orderRepository.findById(orderId).orElseThrow();
        // customer already loaded (EAGER) — no extra query
        System.out.println(order.getCustomer().getName());
        // items NOT loaded yet (LAZY) — accessing triggers a SELECT now
        order.getItems().forEach(item -> System.out.println(item.getProduct()));
    }
}
