import jakarta.persistence.*;
import org.springframework.transaction.annotation.Transactional;

// PROBLEM: accessing a lazy collection after the transaction closed
@org.springframework.web.bind.annotation.RestController
class OrderController {
    private final OrderRepository orderRepository;
    OrderController(OrderRepository r) { this.orderRepository = r; }

    @org.springframework.web.bind.annotation.GetMapping("/orders/{id}")
    public int getOrderItemCountBad(Long id) {
        Order order = orderRepository.findById(id).orElseThrow();
        // transaction already ended -> session closed
        return order.getItems().size(); // LazyInitializationException!
    }
}

// FIX 1: widen the transaction to cover the data access
@org.springframework.stereotype.Service
class OrderService {
    private final OrderRepository orderRepository;
    OrderService(OrderRepository r) { this.orderRepository = r; }

    @Transactional(readOnly = true) // session stays open for the whole method
    public int getItemCount(Long id) {
        Order order = orderRepository.findById(id).orElseThrow();
        return order.getItems().size(); // works — inside the transaction
    }
}

// FIX 2: load the data upfront with @EntityGraph
interface OrderRepository extends JpaRepository<Order, Long> {
    @org.springframework.data.jpa.repository.EntityGraph(attributePaths = "items")
    java.util.Optional<Order> findById(Long id);
}
