import jakarta.persistence.*;
import java.util.*;
import org.springframework.data.jpa.repository.*;

@Entity
public class Order {
    @Id @GeneratedValue private Long id;

    @OneToMany(mappedBy = "order")  // LAZY by default
    private List<OrderItem> items = new ArrayList<>();

    @ManyToOne                       // EAGER by default; can be overridden
    private Customer customer;
}

public interface OrderRepository extends JpaRepository<Order, Long> {

    @EntityGraph(attributePaths = {"items"})         // orders + items, one query
    List<Order> findAll();

    @EntityGraph(attributePaths = {"items", "customer"}) // both associations
    Optional<Order> findById(Long id);

    @EntityGraph(attributePaths = {"items", "items.product"}) // nested path
    List<Order> findByStatus(String status);
}
// Each call runs a single SQL query with JOINs — no N+1.
