import org.springframework.data.jpa.repository.*;

public interface OrderRepository extends JpaRepository<Order, Long> {
    // JOIN FETCH loads orders AND items in a single SQL query
    @Query("SELECT DISTINCT o FROM Order o JOIN FETCH o.items WHERE o.status = :status")
    java.util.List<Order> findByStatusOptimized(@Param("status") String status);
}

// Usage: items already loaded, no extra queries when iterating
// orders.forEach(o -> o.getItems().forEach(i -> print(i.getProductName())));
