import jakarta.persistence.*;
import java.util.*;
import org.springframework.data.jpa.repository.*;

@Entity
public class Customer {
    @Id @GeneratedValue private Long id;
    private String name;

    @OneToMany(mappedBy = "customer", fetch = FetchType.LAZY) // lazy baseline
    private List<Order> orders;
}

public interface CustomerRepository extends JpaRepository<Customer, Long> {

    // Use case 1: list customers only — orders not needed, stays fast
    List<Customer> findAll();

    // Use case 2: customer detail page — need orders -> JOIN FETCH
    @Query("SELECT c FROM Customer c JOIN FETCH c.orders WHERE c.id = :id")
    Optional<Customer> findByIdWithOrders(@Param("id") Long id);

    // Use case 3: several customers with orders -> @EntityGraph batches it
    @EntityGraph(attributePaths = {"orders"})
    List<Customer> findByStatusIn(List<String> statuses);
}
